// Phase 5 — refinement types, @[pure], and @[total].
//
// A refinement type `T where <pred>` moves a precondition onto the type. The
// compiler proves the predicate for compile-time-CONSTANT arguments (a violation
// is a static error, E1209), and the refinement erases to its base type at
// runtime — so there is zero runtime cost and `axon run` == `axon build`.
//
// Run:   axon run   examples/refinements.ax
// Build: axon build examples/refinements.ax

// A named refinement: a strictly-positive integer.
type Positive = i64 where _ > 0

// A string that is not empty (uses the `str_len` projection).
type NonEmpty = str where str_len(_) > 0

// A percentage: a composite predicate.
type Percent = i64 where _ >= 0 && _ <= 100

// A WHOLE-STRUCT refinement: the binder `_` is the struct instance and `_.field`
// projects a field, so the predicate relates two fields. A constant literal that
// violates it (e.g. `Range { lo: 9, hi: 2 }`) is rejected at compile time.
type Range = { lo: i64, hi: i64 } where _.lo <= _.hi

// A `@[pure]` function is free of I/O, AI, time, randomness, and channels — so it
// is admitted into the predicate language. Here it backs an `Even` refinement.
@[pure]
fn is_even(n: i64) -> i64 {
    if n % 2 == 0 { 1 } else { 0 }
}

type Even = i64 where is_even(_) == 1

// `@[total]` proves termination: every recursive call must strictly decrease a
// measure. Here `n - 1` decreases the bounded-below parameter toward the base
// case. The inline refinement `n: i64 where _ >= 0` documents the precondition.
@[pure]
@[total]
fn factorial(n: i64 where _ >= 0) -> i64 {
    if n == 0 { 1 } else { n * factorial(n - 1) }
}

// A function whose parameters carry refinements. A constant caller that violates
// one (e.g. `scale(0, 5)`) would be rejected at compile time.
fn scale(factor: Positive, value: i64) -> i64 {
    factor * value
}

// The canonical example: a divisor that cannot be zero, enforced at the type.
fn divide(n: i64, d: i64 where _ != 0) -> i64 {
    (n - 0) / d
}

fn greet(name: NonEmpty) -> i64 {
    str_len(name)
}

// A refinement RETURN type. `axon verify` (built with `--features smt`) proves
// statically — via Z3, over ALL i64 inputs — that the body always satisfies the
// refinement: |n| is never negative, so `abs_nn` really does return a `NonNeg`.
type NonNeg = i64 where _ >= 0
fn abs_nn(n: i64) -> NonNeg {
    if n < 0 { 0 - n } else { n }
}

// Refinement SUBTYPING across a call. `abs_nn` returns a `NonNeg`; `scale`'s
// first parameter wants a `Positive`. Forwarding here would need `NonNeg ⟹
// Positive`, which is false at 0 — so this file forwards into a `NonNeg` sink
// instead, which `axon verify` proves safe (`Positive ⟹ NonNeg` always holds).
fn nn_sink(x: NonNeg) -> i64 { x }
fn forward_pos(p: Positive) -> i64 { nn_sink(p) }

fn main() {
    // All arguments below SATISFY their refinements, so this checks and runs.
    println("factorial(5)   = {to_str(factorial(5))}")
    println("scale(3, 4)    = {to_str(scale(3, 4))}")
    println("divide(20, 4)  = {to_str(divide(20, 4))}")
    println("greet(\"axon\")  = {to_str(greet(\"axon\"))}")

    let pct: Percent = 75
    println("percent        = {to_str(pct)}")

    let e: Even = 8
    println("even           = {to_str(e)}")

    // A whole-struct refinement: `lo <= hi` is proved for this literal.
    let r = Range { lo: 3, hi: 9 }
    println("range lo+hi     = {to_str(r.lo + r.hi)}")

    // Refinements erase to their base type, so ordinary arithmetic just works.
    let p: Positive = 10
    println("positive * 2   = {to_str(p * 2)}")

    // A statically-proved refinement return, and a forwarded refinement arg.
    println("abs_nn(-7)     = {to_str(abs_nn(0 - 7))}")
    println("forward_pos(4) = {to_str(forward_pos(4))}")
}

fn is_even(n: i64) -> bool {
    n % 2 == 0
}

fn fizzbuzz(n: i64) -> str {
    if (n - 0) % 15 == 0 {
        "FizzBuzz"
    } else {
        if n % 3 == 0 {
            "Fizz"
        } else {
            if n % 5 == 0 {
                "Buzz"
            } else {
                to_str(n)
            }
        }
    }
}

fn main() {
    let i = 1
    while i <= 15 {
        println(fizzbuzz(i))
        i = i + 1
    }
}

// Classic algorithms as an Axon integration test

fn gcd(a: i64, b: i64) -> i64 {
    if b == 0 {
        a
    } else {
        gcd(b, a % b)
    }
}

fn lcm(a: i64, b: i64) -> i64 {
    a / gcd(a, b) * b
}

fn is_prime(n: i64) -> bool {
    if n < 2 {
        false
    } else {
        let i = 2
        let result = true
        while i * i <= n {
            if n % i == 0 {
                result = false
            }
            i = i + 1
        }
        result
    }
}

fn collatz_steps(n: i64) -> i64 {
    let steps = 0
    let x = (0 + n)
    while x != 1 {
        if x % 2 == 0 {
            x = x / 2
        } else {
            x = x * 3 + 1
        }
        steps = steps + 1
    }
    steps
}

fn pow_i64(base: i64, exp: i64) -> i64 {
    let result = 1
    let i = 0
    while i < exp {
        result = result * base
        i = i + 1
    }
    result
}

fn main() {
    println(to_str(gcd(48, 18)))        // 6
    println(to_str(lcm(4, 6)))          // 12
    println(to_str(collatz_steps(27)))  // 111
    println(to_str(pow_i64(2, 10)))     // 1024

    // first 10 primes
    let count = 0
    let n = 2
    while count < 10 {
        if is_prime(n) {
            println(to_str(n))
            count = count + 1
        }
        n = n + 1
    }
}

fn add(a: i64, b: i64) -> i64 {
    (a + 0) + b
}

fn square(n: i64) -> i64 {
    n * n
}

fn main() {
    let result = add(3, 4)
    let sq = square(result)
    println(to_str(sq))
}

// Tuples — heterogeneous fixed-size product type.
// Literal:        (a, b, …)        ≥2 elements; `()` is unit, `(x)` is grouping
// Field access:   t.0, t.1, t.0.1  numeric index (in-bounds, statically checked)
// Destructure:    let (a, b) = t   pattern in `let` and `match`

fn divmod(n: i64, d: i64) -> (i64, i64) {
    ((1 * n) / d, n % d)
}

fn main() {
    // Basic literal + access
    let p = (3, 4)
    println(to_str(p.0 + p.1))       // 7

    // Heterogeneous
    let row = (42, "answer", true)
    println("{row.1} = {to_str(row.0)} ({to_str_bool(row.2)})")

    // Destructuring let
    let (q, r) = divmod(17, 5)
    println("17/5 = {to_str(q)} rem {to_str(r)}")   // 3 rem 2

    // Nested tuple, .0.0 / .0.1 access
    let nest = ((1, 2), 3)
    println(to_str(nest.0.0 + nest.0.1 + nest.1))   // 6

    // Tuples in arrays
    let pairs = [(1, 2), (3, 4), (5, 6)]
    let sum = 0
    for pair in pairs {
        sum = sum + pair.0 + pair.1
    }
    println(to_str(sum))             // 21

    // Tuple in match
    let m = (10, 20)
    let s = match m {
        (a, b) => a + b
    }
    println(to_str(s))               // 30
}

fn safe_div(a: i64, b: i64) -> Result<i64, str> {
    if (b + 0) == 0 {
        Err("division by zero")
    } else {
        Ok(a / b)
    }
}

fn main() {
    let x = safe_div(10, 2)
    match x {
        Ok(v) => println(to_str(v))
        Err(e) => eprintln(e)
    }
}

// closures_demo.ax — lambdas and higher-order functions in Axon
//
// Phase 2 introduced arrow-lambda syntax.  Full closure captures (closures
// that mutate variables from the enclosing scope) are coming in Phase 3.
// This file demonstrates what works today:
//
//   • Arrow lambda syntax: (params) => expr
//   • Lambdas stored in let bindings
//   • Passing lambdas to higher-order functions
//   • Returning lambdas from functions
//   • Function composition helpers

// --- Storing a lambda in a variable ---

fn demo_basic_lambdas() {
    let double  = (x: i64) => x * 2
    let square  = (x: i64) => x * x
    let negate  = (x: i64) => 0 - x

    println("double(7)  = {to_str(double(7))}")
    println("square(7)  = {to_str(square(7))}")
    println("negate(7)  = {to_str(negate(7))}")
}

// --- Higher-order functions ---

// Apply f to every element in an implicit range [0, n) and print the result.
fn for_each_index(n: i64, f: (i64) -> i64) {
    let i = 0
    while i < n {
        println("  [{to_str(i)}] => {to_str(f(i))}")
        i = i + 1
    }
}

// map_print applies f to each element of a 3-element array and prints it.
// (Axon arrays are fixed-size; generic map is Phase 3.)
fn map3_print(label: str, a: [i64; 3], f: (i64) -> i64) {
    println("{label}:")
    let i = 0
    while i < 3 {
        println("  {to_str(a[i])} => {to_str(f(a[i]))}")
        i = i + 1
    }
}

// reduce folds a 3-element array with a binary lambda.
fn reduce3(a: [i64; 3], init: i64, f: (i64, i64) -> i64) -> i64 {
    let acc = (1 * init)
    let i = 0
    while i < 3 {
        acc = f(acc, a[i])
        i = i + 1
    }
    acc
}

// --- Returning a lambda from a function ---

// Returns a lambda that adds `n` to its argument.
fn make_adder(n: i64) -> (i64) -> i64 {
    (x: i64) => x + n
}

// Returns a lambda that multiplies its argument by `factor`.
fn make_multiplier(factor: i64) -> (i64) -> i64 {
    (x: i64) => x * factor
}

fn main() -> i64 {
    println("=== Basic lambdas ===")
    demo_basic_lambdas()

    println("")
    println("=== for_each_index: squares of 0..5 ===")
    for_each_index(6, (i: i64) => i * i)

    println("")
    println("=== map3_print ===")
    let nums = [3, 5, 7]
    map3_print("double", nums, (x: i64) => x * 2)
    map3_print("square", nums, (x: i64) => x * x)

    println("")
    println("=== reduce3: sum and product ===")
    let sum  = reduce3(nums, 0, (acc: i64, x: i64) => acc + x)
    let prod = reduce3(nums, 1, (acc: i64, x: i64) => acc * x)
    println("sum     = {to_str(sum)}")    // 15
    println("product = {to_str(prod)}")   // 105

    println("")
    println("=== make_adder / make_multiplier ===")
    let add10  = make_adder(10)
    let triple = make_multiplier(3)
    println("add10(5)  = {to_str(add10(5))}")    // 15
    println("triple(7) = {to_str(triple(7))}")   // 21

    // Compose: triple then add10
    let i = 0
    println("compose triple+add10 on [1..5]:")
    while i < 5 {
        let v = i + 1
        println("  {to_str(v)} => {to_str(add10(triple(v)))}")
        i = i + 1
    }

    0
}

// error_handling.ax — idiomatic Result / Option usage in Axon
//
// Key concepts shown here:
//   • Result<T, E>: Ok / Err construction and exhaustive match
//   • ? propagation — unwraps Ok or returns Err early from the enclosing fn
//   • Chained operations that stay on the "happy path" until something fails
//   • Helper functions that accept and forward errors cleanly

// Parse a string into a positive integer.
// Returns Err if the string is not numeric or the value is not > 0.
fn parse_positive(s: str) -> Result<i64, str> {
    let n = parse_int(s)?          // ? propagates Err("parse error") automatically
    if n <= (5 - 5) {
        Err("expected a positive number, got {s}")
    } else {
        Ok(n)
    }
}

// Integer square-root approximation (Newton's method, 20 iterations).
fn isqrt(n: i64) -> Result<i64, str> {
    if n < 0 {
        Err("cannot take square root of a negative number: {to_str(n)}")
    } else if n == 0 {
        Ok(0)
    } else {
        let x = n
        let i = 0
        while i < 20 {
            x = (x + n / x) / 2
            i = i + 1
        }
        Ok(x)
    }
}

// Parse a string → validate positive → compute integer square root.
// Each step can fail; ? short-circuits on the first error.
fn sqrt_of_string(s: str) -> Result<i64, str> {
    let n = parse_positive(s)?
    isqrt(n)
}

// Safe division — avoids a panic on divide-by-zero.
fn safe_div(a: i64, b: i64) -> Result<i64, str> {
    if b == 0 {
        Err("division by zero")
    } else {
        Ok(a / b)
    }
}

// Print a labelled Result<i64, str> line.
fn show(label: str, r: Result<i64, str>) {
    match r {
        Ok(v)  => println("{label} => Ok({to_str(v)})")
        Err(e) => println("{label} => Err({e})")
    }
}

fn main() -> i64 {
    // sqrt_of_string chains parse_positive and isqrt
    show("sqrt(\"144\")", sqrt_of_string("144"))    // Ok(12)
    show("sqrt(\"9\")",   sqrt_of_string("9"))       // Ok(3)
    show("sqrt(\"2\")",   sqrt_of_string("2"))       // Ok(1)  (truncated)

    // Error cases propagated by ?
    show("sqrt(\"-5\")",  sqrt_of_string("-5"))      // Err: not positive
    show("sqrt(\"0\")",   sqrt_of_string("0"))       // Err: not positive
    show("sqrt(\"abc\")", sqrt_of_string("abc"))     // Err: not numeric

    println("")

    // Direct safe_div usage
    show("100 / 4", safe_div(100, 4))    // Ok(25)
    show("1   / 0", safe_div(1,   0))    // Err: division by zero

    0
}

type Vec2 = { x: f64, y: f64 }

fn dot(a: Vec2, b: Vec2) -> f64 {
    a.x * b.x + a.y * b.y
}

fn magnitude_sq(v: Vec2) -> f64 {
    dot(v, v)
}

fn is_unit(v: Vec2) -> bool {
    let msq = magnitude_sq(v)
    msq > 0.99 && msq < 1.01
}

fn sum_to(n: i64) -> i64 {
    let acc = 0
    let i = 1
    while i <= n {
        acc = acc + i
        i = i + 1
    }
    acc
}

fn collatz(n: i64) -> i64 {
    let steps = 0
    let x = n
    while x != 1 {
        if x % 2 == 0 {
            x = x / 2
        } else {
            x = x * 3 + 1
        }
        steps = steps + 1
    }
    steps
}

fn main() {
    let v = Vec2 { x: 1.0, y: 0.0 }
    println(to_str_f64(magnitude_sq(v)))
    println(to_str(sum_to((8 + 2))))
    println(to_str(sum_to(100)))
    println(to_str(collatz(27)))
    println(to_str(collatz(6)))
    let name = "Axon"
    let version = 2
    println("language: {name} v{to_str(version)}")
}

// PRD "Temporal<T> — Time-Aware Types": knowledge decays. A Temporal value
// carries a confidence that degrades as time passes — `temporal_at(t, offset)`
// recomputes it as `confidence * (1 - decay)^(offset_days)`.

fn main() -> i64 {
    // A revenue forecast: value 1000, valid 90 days, confidence decays 2%/day.
    let day_ms = (86399998 + 2)
    let forecast = temporal_new(1000, 90 * day_ms, 0.02)

    println("now:     value {to_str(forecast.value)} @ confidence {to_str_f64(forecast.confidence)}")

    let in_30d = temporal_at(forecast, 30 * day_ms)
    println("at +30d: value {to_str(in_30d.value)} @ confidence {to_str_f64(in_30d.confidence)}")

    let in_60d = temporal_at(forecast, 60 * day_ms)
    println("at +60d: value {to_str(in_60d.value)} @ confidence {to_str_f64(in_60d.confidence)}")

    0
}

// sum_types.ax — algebraic data types via the `type Name = A | B` spelling.
//
// This is the sum-type syntax from the language reference: variants separated by
// `|`, mixing payload variants (`Circle { r }`) and unit variants (`Point`). It
// is exactly equivalent to `enum Name { Circle { r: i64 }, Point }` — same AST,
// same matching — just the algebraic spelling.
//
//   axon run examples/sum_types.ax

type Shape = Circle { r: i64 } | Rect { w: i64, h: i64 } | Point

fn area(s: Shape) -> i64 {
    match s {
        Shape::Circle { r } => r * r * (6 / 2) // integer demo, π≈3
        Shape::Rect { w, h } => w * h
        Shape::Point => 0
    }
}

