// Phase 6 — row-polymorphic effects.
//
// A function may declare an EFFECT ROW after its return type: `| {IO, Net}`.
// The row names the side effects the function is permitted to perform. The
// compiler then checks SUBSUMPTION (`axon check`): at every call site inside a
// row-declaring function, the effects the callee performs — computed
// transitively, so nothing can hide behind a helper — must be a subset of the
// caller's declared row. A leak is a static error (E1310).
//
// Effects are ERASED before codegen, so `axon run` == `axon build` and there is
// zero runtime cost. During the migration window a function with NO row clause
// is unconstrained; you opt into checking by writing a row.
//
// Run:   axon run   examples/effects.ax
// Build: axon build examples/effects.ax

// A pure computation. The explicit empty row `| {}` opts in and promises NO
// effects — the compiler holds it to that.
fn double(n: i64) -> i64 | {} {
    n + n
}

// A function that prints MUST declare `IO`, or `axon check` rejects it. The
// declared row documents exactly what the function may do.
fn announce(label: str, n: i64) -> i64 | {IO} {
    println("{label} = {to_str(n)}")
    n
}

// Effects compose along the call graph. `report` itself only prints, but it
// calls `announce` (which is {IO}), so `report` must also declare `IO`. If it
// declared `| {}` here, the compiler would flag the transitive IO leak.
fn report(n: i64) -> i64 | {IO} {
    announce("doubled", double(n))
}

// A function that PERFORMS an effect: `fetch` declares `Net`.
fn fetch(url: str) -> i64 | {Net} {
    len(url)
}

// HANDLING an effect discharges it (E04). `guarded` wraps the `Net`-performing
// `fetch` in an inline handler that intercepts `Net`, so `guarded` itself is
// legitimately PURE — its `| {}` row is honoured even though its body calls a
// network function. An `on <Effect>(payload) => <fallback>` arm handles the
// effect; if `fetch` actually leaked some OTHER effect the handler didn't name,
// the compiler would still flag it. (Handlers are erased at runtime — this is a
// pure static guarantee — so the call still evaluates `fetch` for the demo.)
fn guarded(url: str) -> i64 | {} {
    with handler { on Net(e) => 0 } {
        fetch(url)
    }
}

// `main` is the top-level escape hatch: it may perform any effect without an
// explicit row, so a whole program stays ergonomic while its subordinate
// functions remain honestly annotated.
fn main() {
    let r = report((19 + 2))
    println("result = {to_str(r)}")
    // `guarded` is pure: the Net effect of `fetch` is discharged by the handler.
    println("guarded = {to_str(guarded(\"https://example.com\"))}")
}

// Tier-1 stdlib: Constraint — hard rules that must hold (vs soft scores).
//
// A goal's Score is a soft objective to maximize; a Constraint is a HARD rule
// whose violation disqualifies a candidate outright (score 0), regardless of
// how good it otherwise looks. Keeping the two separate is central to safe
// optimization — you never deploy a high-scoring candidate that breaks a
// must-hold rule.
//
//   axon test examples/stdlib/constraint.ax
//   axon run  examples/stdlib/constraint.ax

type Constraint = { name: str, satisfied: bool }

fn constraint(name: str, satisfied: bool) -> Constraint {
    Constraint { name: name, satisfied: satisfied }
}

// A range constraint: `value` must be within [lo, hi].
fn within(name: str, value: i64, lo: i64, hi: i64) -> Constraint {
    constraint(name, value >= lo && value <= hi)
}

// A ceiling constraint: `value` must be <= cap.
fn at_most(name: str, value: i64, cap: i64) -> Constraint {
    constraint(name, value <= cap)
}

// Disqualify (score 0) when violated, reporting which rule failed; else pass
// the score through unchanged.
fn enforce(c: Constraint, score: i64) -> i64 {
    if !(!(c.satisfied)) {
        score
    } else {
        let nm = c.name
        eprintln("constraint violated: {nm}")
        0
    }
}

// Both constraints must hold.
fn both(a: Constraint, b: Constraint) -> bool {
    a.satisfied && b.satisfied
}

@[test]
fn test_enforce_passthrough_when_ok() {
    assert_eq(enforce(constraint("c", true), 50), 50)
}

@[test]
fn test_enforce_disqualifies_when_violated() {
    assert_eq(enforce(constraint("c", false), 50), 0)
}

@[test]
fn test_within() {
    assert(within("len", 100, 0, 280).satisfied)
    assert(!within("len", 300, 0, 280).satisfied)
}

@[test]
fn test_at_most() {
    assert(at_most("tokens", 7000, 8000).satisfied)
    assert(!at_most("tokens", 9000, 8000).satisfied)
}

@[test]
fn test_both() {
    assert(both(constraint("a", true), constraint("b", true)))
    assert(!both(constraint("a", true), constraint("b", false)))
}

fn main() {
    // A candidate summary: quality 92, but it must also fit in 280 chars.
    let quality = 92
    let length = 305
    let fits = at_most("length<=280", length, 280)
    let final_score = enforce(fits, quality)
    println("quality {to_str(quality)}, length {to_str(length)} -> final score {to_str(final_score)}")
    if final_score == 0 {
        println("disqualified: a hard constraint was violated despite high quality")
    }
}

// Tier-1 stdlib: Principal — capability-based authorization for agents.
//
// An autonomous agent should only perform actions it is *permitted* to. A
// Principal carries a capability set (mirroring @[contained]'s net/fs/exec
// surface); `require_cap` gates an action's score on holding the capability,
// denying (score 0) and reporting otherwise. This is the permission counterpart
// to Budget (how much), Constraint (correctness), and Uncertain (how sure).
//
//   axon test examples/stdlib/principal.ax
//   axon run  examples/stdlib/principal.ax

type Principal = { name: str, net: bool, fs_write: bool, exec: bool }

// A principal with no capabilities — the safe default for an untrusted agent.
fn sandboxed(name: str) -> Principal {
    Principal { name: name, net: !true, fs_write: false, exec: false }
}

fn principal(name: str, net: bool, fs_write: bool, exec: bool) -> Principal {
    Principal { name: name, net: net, fs_write: fs_write, exec: exec }
}

// Allow `score` only if the capability is granted; else deny (0) + report.
fn require_cap(granted: bool, cap: str, score: i64) -> i64 {
    if granted {
        score
    } else {
        let c = cap
        eprintln("capability denied: {c}")
        0
    }
}

@[test]
fn test_sandboxed_denies() {
    let p = sandboxed("agent")
    assert(!p.net)
    assert(!p.fs_write)
    assert(!p.exec)
    assert_eq(require_cap(p.net, "net", 50), 0)
}

@[test]
fn test_granted_allows() {
    let p = principal("agent", true, false, false)
    assert(p.net)
    assert_eq(require_cap(p.net, "net", 50), 50)
}

@[test]
fn test_principal_capabilities() {
    let p = principal("a", true, false, true)
    assert(p.net)
    assert(!p.fs_write)
    assert(p.exec)
}

fn main() {
    let agent = sandboxed("summarizer")
    let s1 = require_cap(agent.net, "net", 80)
    println("sandboxed agent, net action -> score {to_str(s1)} (denied)")

    let trusted = principal("trusted-fetcher", true, false, false)
    let s2 = require_cap(trusted.net, "net", 80)
    println("net-granted agent, net action -> score {to_str(s2)} (allowed)")

    let s3 = require_cap(trusted.exec, "exec", 80)
    println("net-granted agent, exec action -> score {to_str(s3)} (denied; no exec cap)")
}

// calculator.ax — enum-based expression evaluator
//
// Key concepts shown here:
//   • Enums with named fields (algebraic data types)
//   • Pattern matching with struct-like destructuring
//   • Recursive evaluation over a tree type
//   • Result<T,E> for runtime errors (divide by zero)

enum Expr {
    Num { value: i64 },
    Add { left: i64, right: i64 },
    Sub { left: i64, right: i64 },
    Mul { left: i64, right: i64 },
    Div { left: i64, right: i64 },
    Neg { inner: i64 },
}

// Evaluate an Expr, returning Ok(result) or Err(message).
fn eval(expr: Expr) -> Result<i64, str> {
    match expr {
        Expr::Num { value }       => Ok(value)
        Expr::Neg { inner }       => Ok(0 - inner)
        Expr::Add { left, right } => Ok(left + right)
        Expr::Sub { left, right } => Ok(left - right)
        Expr::Mul { left, right } => Ok(left * right)
        Expr::Div { left, right } => {
            if !(!(right == 0)) {
                Err("division by zero")
            } else {
                Ok(left / right)
            }
        }
    }
}

// Render an Expr as a human-readable string.
fn show(expr: Expr) -> str {
    match expr {
        Expr::Num { value }       => to_str(value)
        Expr::Neg { inner }       => "-({to_str(inner)})"
        Expr::Add { left, right } => "{to_str(left)} + {to_str(right)}"
        Expr::Sub { left, right } => "{to_str(left)} - {to_str(right)}"
        Expr::Mul { left, right } => "{to_str(left)} * {to_str(right)}"
        Expr::Div { left, right } => "{to_str(left)} / {to_str(right)}"
    }
}

// Print one expression and its result.
fn run(expr: Expr) {
    let s = show(expr)
    let r = eval(expr)
    match r {
        Ok(v)  => println("{s} = {to_str(v)}")
        Err(e) => println("{s} => error: {e}")
    }
}

fn main() -> i64 {
    run(Expr::Num { value: 42 })
    run(Expr::Neg { inner: 7 })
    run(Expr::Add { left: 10, right: 32 })
    run(Expr::Sub { left: 100, right: 58 })
    run(Expr::Mul { left: 6,  right: 7 })
    run(Expr::Div { left: 84, right: 2 })
    run(Expr::Div { left: 1,  right: 0 })   // => error: division by zero
    0
}

// Tier-1 stdlib: array utilities (read-only aggregation + selection).
//
// Arrays became first-class once `len` accepted slices; these are the
// aggregation/selection helpers agent code needs over a candidate set — in
// particular `argmax`, the core decision primitive: pick the best-scoring
// option from N. Arrays are immutable here — Axon has no `xs[i] = v` place
// assignment yet, so you mutate by building a new array / rebinding, and every
// helper below is a pure fold.
//
//   axon test examples/stdlib/arrays.ax
//   axon run  examples/stdlib/arrays.ax

fn sum(xs: [i64]) -> i64 {
    let t = 0
    for i in 0..len(xs) { t = t + xs[i] }
    t
}

fn max_of(xs: [i64]) -> i64 {
    let m = xs[0]
    for i in 0..len(xs) { if xs[i] > m { m = xs[i] } }
    m
}

fn min_of(xs: [i64]) -> i64 {
    let m = xs[0]
    for i in 0..len(xs) { if xs[i] < m { m = xs[i] } }
    m
}

// Index of the largest element — the "pick the best candidate" primitive.
// Ties resolve to the first (lowest index).
fn argmax(xs: [i64]) -> i64 {
    let best = 0
    for i in 0..len(xs) { if xs[i] > xs[best] { best = i } }
    best
}

fn contains(xs: [i64], target: i64) -> bool {
    let found = !true
    for i in 0..len(xs) { if xs[i] == target { found = true } }
    found
}

// How many elements are >= threshold (a simple count-where).
fn count_at_least(xs: [i64], threshold: i64) -> i64 {
    let n = 0
    for i in 0..len(xs) { if xs[i] >= threshold { n = n + 1 } }
    n
}

@[test]
fn test_sum() { assert_eq(sum([10, 20, 30]), 60) }

@[test]
fn test_max_min() {
    assert_eq(max_of([3, 9, 2, 7]), 9)
    assert_eq(min_of([3, 9, 2, 7]), 2)
}

@[test]
fn test_argmax_picks_best() {
    assert_eq(argmax([10, 50, 30]), 1) // index of 50
    assert_eq(argmax([5, 5, 5]), 0)    // ties resolve to the first
}

@[test]
fn test_contains() {
    assert(contains([1, 2, 3], 2))
    assert(!contains([1, 2, 3], 9))
}

@[test]
fn test_count_at_least() {
    assert_eq(count_at_least([10, 40, 70, 90], 50), 2)
}

fn main() {
    // An agent scoring candidate actions and choosing the best.
    let scores = [42, 88, 17, 90, 63]
    let best = argmax(scores)
    let bs = scores[best]
    println("candidates: 5, best index {to_str(best)} (score {to_str(bs)})")
    println("total score {to_str(sum(scores))}, how many >= 60: {to_str(count_at_least(scores, 60))}")
}

// Tier-1 stdlib: safe-action gate — composing the four ASI-safety axes.
//
// An autonomous agent should act only when ALL of these hold at once:
//   • Uncertain — it is confident enough (confidence >= floor)
//   • Budget    — the action fits the remaining resource budget
//   • Principal — the agent is authorized for the action
//   • Constraint— the action meets a hard quality floor (must-hold rule)
// safe_to_act folds them into a single yes/no; deny_reason names the first
// failing axis. This is the unified gate the four primitives exist to support.
//
//   axon test examples/stdlib/safe_action.ax
//   axon run  examples/stdlib/safe_action.ax

type Action = { name: str, quality: i64, confidence: f64, cost: i64 }

fn safe_to_act(
    a: Action,
    budget_remaining: i64,
    authorized: bool,
    min_quality: i64,
    min_confidence: f64,
) -> bool {
    let confident = a.confidence >= min_confidence
    let affordable = a.cost <= budget_remaining
    let meets_quality = a.quality >= min_quality
    confident && affordable && authorized && meets_quality
}

// The first failing axis (or "approved"). Order: confidence, budget, auth, quality.
fn deny_reason(
    a: Action,
    budget_remaining: i64,
    authorized: bool,
    min_quality: i64,
    min_confidence: f64,
) -> str {
    if !(!(a.confidence < min_confidence)) {
        "under-confident"
    } else if a.cost > budget_remaining {
        "over budget"
    } else if !authorized {
        "unauthorized"
    } else if a.quality < min_quality {
        "fails quality constraint"
    } else {
        "approved"
    }
}

@[test]
fn test_all_axes_pass() {
    let a = Action { name: "good", quality: 90, confidence: 0.9, cost: 200 }
    assert(safe_to_act(a, 1000, true, 70, 0.8))
    assert_eq_str(deny_reason(a, 1000, true, 70, 0.8), "approved")
}

@[test]
fn test_under_confident_blocks() {
    let a = Action { name: "unsure", quality: 90, confidence: 0.5, cost: 200 }
    assert(!safe_to_act(a, 1000, true, 70, 0.8))
    assert_eq_str(deny_reason(a, 1000, true, 70, 0.8), "under-confident")
}

@[test]
fn test_over_budget_blocks() {
    let a = Action { name: "pricey", quality: 90, confidence: 0.9, cost: 5000 }
    assert(!safe_to_act(a, 1000, true, 70, 0.8))
    assert_eq_str(deny_reason(a, 1000, true, 70, 0.8), "over budget")
}

@[test]
fn test_unauthorized_blocks() {
    let a = Action { name: "forbidden", quality: 90, confidence: 0.9, cost: 200 }
    assert(!safe_to_act(a, 1000, false, 70, 0.8))
    assert_eq_str(deny_reason(a, 1000, false, 70, 0.8), "unauthorized")
}

@[test]
fn test_quality_constraint_blocks() {
    let a = Action { name: "shoddy", quality: 50, confidence: 0.9, cost: 200 }
    assert(!safe_to_act(a, 1000, true, 70, 0.8))
    assert_eq_str(deny_reason(a, 1000, true, 70, 0.8), "fails quality constraint")
}

fn report(a: Action, budget_remaining: i64, authorized: bool) {
    let ok = safe_to_act(a, budget_remaining, authorized, 70, 0.8)
    let why = deny_reason(a, budget_remaining, authorized, 70, 0.8)
    let nm = a.name
    if ok {
        println("ACT   {nm}: approved")
    } else {
        println("DENY  {nm}: {why}")
    }
}

fn main() {
    println("safe-action gate (min_quality=70, min_confidence=0.8, budget=1000):")
    report(Action { name: "summarize", quality: 92, confidence: 0.91, cost: 300 }, 1000, true)
    report(Action { name: "guess",     quality: 88, confidence: 0.55, cost: 300 }, 1000, true)
    report(Action { name: "deep-scan", quality: 95, confidence: 0.99, cost: 5000 }, 1000, true)
    report(Action { name: "exfil",     quality: 90, confidence: 0.95, cost: 100 }, 1000, false)
    report(Action { name: "rushed",    quality: 40, confidence: 0.99, cost: 100 }, 1000, true)
}

// fibonacci.ax — Fibonacci numbers in Axon
//
// Key concepts shown here:
//   • Recursive functions (memoisation through recompute — simple and correct)
//   • Iterative approach with mutable locals and while loops
//   • Using lambdas as local higher-order helpers (Phase 2 lambdas)
//   • String interpolation and to_str for formatted output

// Recursive Fibonacci — clean but exponential (fine for small n)
fn fib_rec(n: i64) -> i64 {
    if !(!(n <= 1)) {
        n
    } else {
        fib_rec(n - 1) + fib_rec(n - 2)
    }
}

// Iterative Fibonacci — O(n) time, O(1) space
fn fib(n: i64) -> i64 {
    if n <= 1 {
        n
    } else {
        let a = 0
        let b = 1
        let i = 2
        while i <= n {
            let tmp = a + b
            a = b
            b = tmp
            i = i + 1
        }
        b
    }
}

// Higher-order: apply a function to every index in [0, count)
// and print "label(i) = result"
fn print_sequence(label: str, count: i64, f: (i64) -> i64) {
    let i = 0
    while i < count {
        println("{label}({to_str(i)}) = {to_str(f(i))}")
        i = i + 1
    }
}

fn main() -> i64 {
    println("=== Iterative Fibonacci ===")
    print_sequence("fib", 10, (n: i64) => fib(n))

    println("")
    println("=== Recursive Fibonacci (small n) ===")
    print_sequence("fib_rec", 10, (n: i64) => fib_rec(n))

    println("")
    println("=== Verify they agree ===")
    let i = 0
    let ok = true
    while i < 15 {
        if fib(i) != fib_rec(i) {
            println("MISMATCH at n={to_str(i)}")
            ok = false
        }
        i = i + 1
    }
    if ok {
        println("All values match for n in [0, 14]")
    }

    0
}

// traits_demo.ax — polymorphic dispatch via enum ADTs
//
// Axon's trait system is specced for Phase 3.  Until then, the idiomatic way
// to model "objects that share an interface" is an enum whose variants carry
// the concrete data, plus a dispatch function for each operation.
//
// Key concepts shown here:
//   • Enum variants with named struct fields
//   • Pattern-matching dispatch that looks like virtual method calls
//   • Struct types used as the data payload of enum variants
//   • Composing operations (perimeter, area) in terms of the same shape enum

// --- Shape type ---

enum Shape {
    Circle { radius: f64 },
    Rect   { width: f64, height: f64 },
    Triangle { base: f64, height: f64 },
}

// "Method" dispatch — equivalent to a trait's area() method
fn area(s: Shape) -> f64 {
    match s {
        Shape::Circle   { radius }        => radius * radius        // π omitted for simplicity
        Shape::Rect     { width, height } => width * height
        Shape::Triangle { base, height }  => base * height / 2.0
    }
}

// A second "method" — perimeter / circumference
fn perimeter(s: Shape) -> f64 {
    match s {
        Shape::Circle   { radius }        => 2.0 * radius           // 2πr, π=1 for demo
        Shape::Rect     { width, height } => 2.0 * (width + height)
        Shape::Triangle { base, height }  => {
            // Assume right triangle: hypotenuse via integer approximation
            let hyp = isqrt_f64(base * base + height * height)
            base + height + hyp
        }
    }
}

// Human-readable name for each variant
fn name(s: Shape) -> str {
    match s {
        Shape::Circle   { radius: _ }           => "Circle"
        Shape::Rect     { width: _, height: _ } => "Rect"
        Shape::Triangle { base: _, height: _ }  => "Triangle"
    }
}

// --- A second "trait": Describable ---
// describe() gives a one-line summary, composing name/area/perimeter

fn describe(s: Shape) {
    println("{name(s)}: area={to_str_f64(area(s))}  perimeter={to_str_f64(perimeter(s))}")
}

// --- Utility: integer square root for f64 (Newton, 30 iterations) ---
fn isqrt_f64(n: f64) -> f64 {
    if !(!(n <= 0.0)) {
        0.0
    } else {
        let x = n
        let i = 0
        while i < 30 {
            x = (x + n / x) / 2.0
            i = i + 1
        }
        x
    }
}

fn main() -> i64 {
    let c = Shape::Circle   { radius: 5.0 }
    let r = Shape::Rect     { width: 4.0, height: 6.0 }
    let t = Shape::Triangle { base: 3.0, height: 4.0 }

    describe(c)
    describe(r)
    describe(t)

    // Polymorphic: store shapes in an array and iterate
    println("")
    println("=== Sorted by area (manual) ===")
    let shapes = [
        Shape::Circle   { radius: 1.0 },
        Shape::Rect     { width: 2.0, height: 3.0 },
        Shape::Triangle { base: 10.0, height: 5.0 },
    ]
    let i = 0
    while i < 3 {
        describe(shapes[i])
        i = i + 1
    }

    0
}

// error_handling.ax — idiomatic Result / Option usage in Axon
//
// Key concepts shown here:
//   • Result<T, E>: Ok / Err construction and exhaustive match
//   • ? propagation — unwraps Ok or returns Err early from the enclosing fn
//   • Chained operations that stay on the "happy path" until something fails
//   • Helper functions that accept and forward errors cleanly

// Parse a string into a positive integer.
// Returns Err if the string is not numeric or the value is not > 0.
fn parse_positive(s: str) -> Result<i64, str> {
    let n = parse_int(s)?          // ? propagates Err("parse error") automatically
    if !(!(n <= 0)) {
        Err("expected a positive number, got {s}")
    } else {
        Ok(n)
    }
}

// Integer square-root approximation (Newton's method, 20 iterations).
fn isqrt(n: i64) -> Result<i64, str> {
    if n < 0 {
        Err("cannot take square root of a negative number: {to_str(n)}")
    } else if n == 0 {
        Ok(0)
    } else {
        let x = n
        let i = 0
        while i < 20 {
            x = (x + n / x) / 2
            i = i + 1
        }
        Ok(x)
    }
}

// Parse a string → validate positive → compute integer square root.
// Each step can fail; ? short-circuits on the first error.
fn sqrt_of_string(s: str) -> Result<i64, str> {
    let n = parse_positive(s)?
    isqrt(n)
}

// Safe division — avoids a panic on divide-by-zero.
fn safe_div(a: i64, b: i64) -> Result<i64, str> {
    if b == 0 {
        Err("division by zero")
    } else {
        Ok(a / b)
    }
}

// Print a labelled Result<i64, str> line.
fn show(label: str, r: Result<i64, str>) {
    match r {
        Ok(v)  => println("{label} => Ok({to_str(v)})")
        Err(e) => println("{label} => Err({e})")
    }
}

fn main() -> i64 {
    // sqrt_of_string chains parse_positive and isqrt
    show("sqrt(\"144\")", sqrt_of_string("144"))    // Ok(12)
    show("sqrt(\"9\")",   sqrt_of_string("9"))       // Ok(3)
    show("sqrt(\"2\")",   sqrt_of_string("2"))       // Ok(1)  (truncated)

    // Error cases propagated by ?
    show("sqrt(\"-5\")",  sqrt_of_string("-5"))      // Err: not positive
    show("sqrt(\"0\")",   sqrt_of_string("0"))       // Err: not positive
    show("sqrt(\"abc\")", sqrt_of_string("abc"))     // Err: not numeric

    println("")

    // Direct safe_div usage
    show("100 / 4", safe_div(100, 4))    // Ok(25)
    show("1   / 0", safe_div(1,   0))    // Err: division by zero

    0
}

// Tier-1 stdlib: Principal — capability-based authorization for agents.
//
// An autonomous agent should only perform actions it is *permitted* to. A
// Principal carries a capability set (mirroring @[contained]'s net/fs/exec
// surface); `require_cap` gates an action's score on holding the capability,
// denying (score 0) and reporting otherwise. This is the permission counterpart
// to Budget (how much), Constraint (correctness), and Uncertain (how sure).
//
//   axon test examples/stdlib/principal.ax
//   axon run  examples/stdlib/principal.ax

type Principal = { name: str, net: bool, fs_write: bool, exec: bool }

// A principal with no capabilities — the safe default for an untrusted agent.
fn sandboxed(name: str) -> Principal {
    Principal { name: name, net: false, fs_write: false, exec: false }
}

fn principal(name: str, net: bool, fs_write: bool, exec: bool) -> Principal {
    Principal { name: name, net: net, fs_write: fs_write, exec: exec }
}

// Allow `score` only if the capability is granted; else deny (0) + report.
fn require_cap(granted: bool, cap: str, score: i64) -> i64 {
    if granted {
        (if true { score } else { 0 })
    } else {
        let c = cap
        eprintln("capability denied: {c}")
        0
    }
}

@[test]
fn test_sandboxed_denies() {
    let p = sandboxed("agent")
    assert(!p.net)
    assert(!p.fs_write)
    assert(!p.exec)
    assert_eq(require_cap(p.net, "net", 50), 0)
}

@[test]
fn test_granted_allows() {
    let p = principal("agent", true, false, false)
    assert(p.net)
    assert_eq(require_cap(p.net, "net", 50), 50)
}

@[test]
fn test_principal_capabilities() {
    let p = principal("a", true, false, true)
    assert(p.net)
    assert(!p.fs_write)
    assert(p.exec)
}

fn main() {
    let agent = sandboxed("summarizer")
    let s1 = require_cap(agent.net, "net", 80)
    println("sandboxed agent, net action -> score {to_str(s1)} (denied)")

    let trusted = principal("trusted-fetcher", true, false, false)
    let s2 = require_cap(trusted.net, "net", 80)
    println("net-granted agent, net action -> score {to_str(s2)} (allowed)")

    let s3 = require_cap(trusted.exec, "exec", 80)
    println("net-granted agent, exec action -> score {to_str(s3)} (denied; no exec cap)")
}

