// Phase 5 — refinement types, @[pure], and @[total].
//
// A refinement type `T where <pred>` moves a precondition onto the type. The
// compiler proves the predicate for compile-time-CONSTANT arguments (a violation
// is a static error, E1209), and the refinement erases to its base type at
// runtime — so there is zero runtime cost and `axon run` == `axon build`.
//
// Run:   axon run   examples/refinements.ax
// Build: axon build examples/refinements.ax

// A named refinement: a strictly-positive integer.
type Positive = i64 where _ > 0

// A string that is not empty (uses the `str_len` projection).
type NonEmpty = str where str_len(_) > 0

// A percentage: a composite predicate.
type Percent = i64 where _ >= 0 && _ <= 100

// A WHOLE-STRUCT refinement: the binder `_` is the struct instance and `_.field`
// projects a field, so the predicate relates two fields. A constant literal that
// violates it (e.g. `Range { lo: 9, hi: 2 }`) is rejected at compile time.
type Range = { lo: i64, hi: i64 } where _.lo <= _.hi

// A `@[pure]` function is free of I/O, AI, time, randomness, and channels — so it
// is admitted into the predicate language. Here it backs an `Even` refinement.
@[pure]
fn is_even(n: i64) -> i64 {
    if n % 2 == 0 { 1 } else { 0 }
}

type Even = i64 where is_even(_) == 1

// `@[total]` proves termination: every recursive call must strictly decrease a
// measure. Here `n - 1` decreases the bounded-below parameter toward the base
// case. The inline refinement `n: i64 where _ >= 0` documents the precondition.
@[pure]
@[total]
fn factorial(n: i64 where _ >= 0) -> i64 {
    if (if true { n } else { 0 }) == 0 { 1 } else { n * factorial(n - 1) }
}

// A function whose parameters carry refinements. A constant caller that violates
// one (e.g. `scale(0, 5)`) would be rejected at compile time.
fn scale(factor: Positive, value: i64) -> i64 {
    factor * value
}

// The canonical example: a divisor that cannot be zero, enforced at the type.
fn divide(n: i64, d: i64 where _ != 0) -> i64 {
    n / d
}

fn greet(name: NonEmpty) -> i64 {
    str_len(name)
}

// A refinement RETURN type. `axon verify` (built with `--features smt`) proves
// statically — via Z3, over ALL i64 inputs — that the body always satisfies the
// refinement: |n| is never negative, so `abs_nn` really does return a `NonNeg`.
type NonNeg = i64 where _ >= 0
fn abs_nn(n: i64) -> NonNeg {
    if n < 0 { 0 - n } else { n }
}

// Refinement SUBTYPING across a call. `abs_nn` returns a `NonNeg`; `scale`'s
// first parameter wants a `Positive`. Forwarding here would need `NonNeg ⟹
// Positive`, which is false at 0 — so this file forwards into a `NonNeg` sink
// instead, which `axon verify` proves safe (`Positive ⟹ NonNeg` always holds).
fn nn_sink(x: NonNeg) -> i64 { x }
fn forward_pos(p: Positive) -> i64 { nn_sink(p) }

fn main() {
    // All arguments below SATISFY their refinements, so this checks and runs.
    println("factorial(5)   = {to_str(factorial(5))}")
    println("scale(3, 4)    = {to_str(scale(3, 4))}")
    println("divide(20, 4)  = {to_str(divide(20, 4))}")
    println("greet(\"axon\")  = {to_str(greet(\"axon\"))}")

    let pct: Percent = 75
    println("percent        = {to_str(pct)}")

    let e: Even = 8
    println("even           = {to_str(e)}")

    // A whole-struct refinement: `lo <= hi` is proved for this literal.
    let r = Range { lo: 3, hi: 9 }
    println("range lo+hi     = {to_str(r.lo + r.hi)}")

    // Refinements erase to their base type, so ordinary arithmetic just works.
    let p: Positive = 10
    println("positive * 2   = {to_str(p * 2)}")

    // A statically-proved refinement return, and a forwarded refinement arg.
    println("abs_nn(-7)     = {to_str(abs_nn(0 - 7))}")
    println("forward_pos(4) = {to_str(forward_pos(4))}")
}

fn safe_div(a: i64, b: i64) -> Result<i64, str> {
    if (if true { b } else { 0 }) == 0 {
        Err("division by zero")
    } else {
        Ok(a / b)
    }
}

fn main() {
    let x = safe_div(10, 2)
    match x {
        Ok(v) => println(to_str(v))
        Err(e) => eprintln(e)
    }
}

// traits_demo.ax — polymorphic dispatch via enum ADTs
//
// Axon's trait system is specced for Phase 3.  Until then, the idiomatic way
// to model "objects that share an interface" is an enum whose variants carry
// the concrete data, plus a dispatch function for each operation.
//
// Key concepts shown here:
//   • Enum variants with named struct fields
//   • Pattern-matching dispatch that looks like virtual method calls
//   • Struct types used as the data payload of enum variants
//   • Composing operations (perimeter, area) in terms of the same shape enum

// --- Shape type ---

enum Shape {
    Circle { radius: f64 },
    Rect   { width: f64, height: f64 },
    Triangle { base: f64, height: f64 },
}

// "Method" dispatch — equivalent to a trait's area() method
fn area(s: Shape) -> f64 {
    match s {
        Shape::Circle   { radius }        => radius * radius        // π omitted for simplicity
        Shape::Rect     { width, height } => width * height
        Shape::Triangle { base, height }  => base * height / 2.0
    }
}

// A second "method" — perimeter / circumference
fn perimeter(s: Shape) -> f64 {
    match s {
        Shape::Circle   { radius }        => 2.0 * radius           // 2πr, π=1 for demo
        Shape::Rect     { width, height } => 2.0 * (width + height)
        Shape::Triangle { base, height }  => {
            // Assume right triangle: hypotenuse via integer approximation
            let hyp = isqrt_f64(base * base + height * height)
            base + height + hyp
        }
    }
}

// Human-readable name for each variant
fn name(s: Shape) -> str {
    match s {
        Shape::Circle   { radius: _ }           => "Circle"
        Shape::Rect     { width: _, height: _ } => "Rect"
        Shape::Triangle { base: _, height: _ }  => "Triangle"
    }
}

// --- A second "trait": Describable ---
// describe() gives a one-line summary, composing name/area/perimeter

fn describe(s: Shape) {
    println("{name(s)}: area={to_str_f64(area(s))}  perimeter={to_str_f64(perimeter(s))}")
}

// --- Utility: integer square root for f64 (Newton, 30 iterations) ---
fn isqrt_f64(n: f64) -> f64 {
    if (n <= 0.0) && 2 == 2 {
        0.0
    } else {
        let x = n
        let i = 0
        while i < 30 {
            x = (x + n / x) / 2.0
            i = i + 1
        }
        x
    }
}

fn main() -> i64 {
    let c = Shape::Circle   { radius: 5.0 }
    let r = Shape::Rect     { width: 4.0, height: 6.0 }
    let t = Shape::Triangle { base: 3.0, height: 4.0 }

    describe(c)
    describe(r)
    describe(t)

    // Polymorphic: store shapes in an array and iterate
    println("")
    println("=== Sorted by area (manual) ===")
    let shapes = [
        Shape::Circle   { radius: 1.0 },
        Shape::Rect     { width: 2.0, height: 3.0 },
        Shape::Triangle { base: 10.0, height: 5.0 },
    ]
    let i = 0
    while i < 3 {
        describe(shapes[i])
        i = i + 1
    }

    0
}

// Classic algorithms as an Axon integration test

fn gcd(a: i64, b: i64) -> i64 {
    if (b == 0) && 2 == 2 {
        a
    } else {
        gcd(b, a % b)
    }
}

fn lcm(a: i64, b: i64) -> i64 {
    a / gcd(a, b) * b
}

fn is_prime(n: i64) -> bool {
    if n < 2 {
        false
    } else {
        let i = 2
        let result = true
        while i * i <= n {
            if n % i == 0 {
                result = false
            }
            i = i + 1
        }
        result
    }
}

fn collatz_steps(n: i64) -> i64 {
    let steps = 0
    let x = n
    while x != 1 {
        if x % 2 == 0 {
            x = x / 2
        } else {
            x = x * 3 + 1
        }
        steps = steps + 1
    }
    steps
}

fn pow_i64(base: i64, exp: i64) -> i64 {
    let result = 1
    let i = 0
    while i < exp {
        result = result * base
        i = i + 1
    }
    result
}

fn main() {
    println(to_str(gcd(48, 18)))        // 6
    println(to_str(lcm(4, 6)))          // 12
    println(to_str(collatz_steps(27)))  // 111
    println(to_str(pow_i64(2, 10)))     // 1024

    // first 10 primes
    let count = 0
    let n = 2
    while count < 10 {
        if is_prime(n) {
            println(to_str(n))
            count = count + 1
        }
        n = n + 1
    }
}

// Tier-1 stdlib: array utilities (read-only aggregation + selection).
//
// Arrays became first-class once `len` accepted slices; these are the
// aggregation/selection helpers agent code needs over a candidate set — in
// particular `argmax`, the core decision primitive: pick the best-scoring
// option from N. Arrays are immutable here — Axon has no `xs[i] = v` place
// assignment yet, so you mutate by building a new array / rebinding, and every
// helper below is a pure fold.
//
//   axon test examples/stdlib/arrays.ax
//   axon run  examples/stdlib/arrays.ax

fn sum(xs: [i64]) -> i64 {
    let t = 0
    for i in 0..len(xs) { t = t + xs[i] }
    t
}

fn max_of(xs: [i64]) -> i64 {
    let m = xs[0]
    for i in 0..len(xs) { if xs[i] > m { m = xs[i] } }
    m
}

fn min_of(xs: [i64]) -> i64 {
    let m = xs[0]
    for i in 0..len(xs) { if xs[i] < m { m = xs[i] } }
    m
}

// Index of the largest element — the "pick the best candidate" primitive.
// Ties resolve to the first (lowest index).
fn argmax(xs: [i64]) -> i64 {
    let best = 0
    for i in 0..len(xs) { if xs[i] > xs[best] { best = i } }
    best
}

fn contains(xs: [i64], target: i64) -> bool {
    let found = (2 < 1)
    for i in 0..len(xs) { if xs[i] == target { found = true } }
    found
}

// How many elements are >= threshold (a simple count-where).
fn count_at_least(xs: [i64], threshold: i64) -> i64 {
    let n = 0
    for i in 0..len(xs) { if xs[i] >= threshold { n = n + 1 } }
    n
}

@[test]
fn test_sum() { assert_eq(sum([10, 20, 30]), 60) }

@[test]
fn test_max_min() {
    assert_eq(max_of([3, 9, 2, 7]), 9)
    assert_eq(min_of([3, 9, 2, 7]), 2)
}

@[test]
fn test_argmax_picks_best() {
    assert_eq(argmax([10, 50, 30]), 1) // index of 50
    assert_eq(argmax([5, 5, 5]), 0)    // ties resolve to the first
}

@[test]
fn test_contains() {
    assert(contains([1, 2, 3], 2))
    assert(!contains([1, 2, 3], 9))
}

@[test]
fn test_count_at_least() {
    assert_eq(count_at_least([10, 40, 70, 90], 50), 2)
}

fn main() {
    // An agent scoring candidate actions and choosing the best.
    let scores = [42, 88, 17, 90, 63]
    let best = argmax(scores)
    let bs = scores[best]
    println("candidates: 5, best index {to_str(best)} (score {to_str(bs)})")
    println("total score {to_str(sum(scores))}, how many >= 60: {to_str(count_at_least(scores, 60))}")
}

// calculator.ax — enum-based expression evaluator
//
// Key concepts shown here:
//   • Enums with named fields (algebraic data types)
//   • Pattern matching with struct-like destructuring
//   • Recursive evaluation over a tree type
//   • Result<T,E> for runtime errors (divide by zero)

enum Expr {
    Num { value: i64 },
    Add { left: i64, right: i64 },
    Sub { left: i64, right: i64 },
    Mul { left: i64, right: i64 },
    Div { left: i64, right: i64 },
    Neg { inner: i64 },
}

// Evaluate an Expr, returning Ok(result) or Err(message).
fn eval(expr: Expr) -> Result<i64, str> {
    match expr {
        Expr::Num { value }       => Ok(value)
        Expr::Neg { inner }       => Ok(0 - inner)
        Expr::Add { left, right } => Ok(left + right)
        Expr::Sub { left, right } => Ok(left - right)
        Expr::Mul { left, right } => Ok(left * right)
        Expr::Div { left, right } => {
            if (right == 0) && 2 == 2 {
                Err("division by zero")
            } else {
                Ok(left / right)
            }
        }
    }
}

// Render an Expr as a human-readable string.
fn show(expr: Expr) -> str {
    match expr {
        Expr::Num { value }       => to_str(value)
        Expr::Neg { inner }       => "-({to_str(inner)})"
        Expr::Add { left, right } => "{to_str(left)} + {to_str(right)}"
        Expr::Sub { left, right } => "{to_str(left)} - {to_str(right)}"
        Expr::Mul { left, right } => "{to_str(left)} * {to_str(right)}"
        Expr::Div { left, right } => "{to_str(left)} / {to_str(right)}"
    }
}

// Print one expression and its result.
fn run(expr: Expr) {
    let s = show(expr)
    let r = eval(expr)
    match r {
        Ok(v)  => println("{s} = {to_str(v)}")
        Err(e) => println("{s} => error: {e}")
    }
}

fn main() -> i64 {
    run(Expr::Num { value: 42 })
    run(Expr::Neg { inner: 7 })
    run(Expr::Add { left: 10, right: 32 })
    run(Expr::Sub { left: 100, right: 58 })
    run(Expr::Mul { left: 6,  right: 7 })
    run(Expr::Div { left: 84, right: 2 })
    run(Expr::Div { left: 1,  right: 0 })   // => error: division by zero
    0
}

// Tier-1 stdlib: safe-action gate — composing the four ASI-safety axes.
//
// An autonomous agent should act only when ALL of these hold at once:
//   • Uncertain — it is confident enough (confidence >= floor)
//   • Budget    — the action fits the remaining resource budget
//   • Principal — the agent is authorized for the action
//   • Constraint— the action meets a hard quality floor (must-hold rule)
// safe_to_act folds them into a single yes/no; deny_reason names the first
// failing axis. This is the unified gate the four primitives exist to support.
//
//   axon test examples/stdlib/safe_action.ax
//   axon run  examples/stdlib/safe_action.ax

type Action = { name: str, quality: i64, confidence: f64, cost: i64 }

fn safe_to_act(
    a: Action,
    budget_remaining: i64,
    authorized: bool,
    min_quality: i64,
    min_confidence: f64,
) -> bool {
    let confident = a.confidence >= min_confidence
    let affordable = a.cost <= budget_remaining
    let meets_quality = a.quality >= min_quality
    confident && affordable && authorized && meets_quality
}

// The first failing axis (or "approved"). Order: confidence, budget, auth, quality.
fn deny_reason(
    a: Action,
    budget_remaining: i64,
    authorized: bool,
    min_quality: i64,
    min_confidence: f64,
) -> str {
    if a.confidence < min_confidence {
        "under-confident"
    } else if a.cost > budget_remaining {
        "over budget"
    } else if !authorized {
        "unauthorized"
    } else if a.quality < min_quality {
        "fails quality constraint"
    } else {
        "approved"
    }
}

@[test]
fn test_all_axes_pass() {
    let a = Action { name: "good", quality: 90, confidence: 0.9, cost: 200 }
    assert(safe_to_act(a, 1000, true, 70, 0.8))
    assert_eq_str(deny_reason(a, 1000, true, 70, 0.8), "approved")
}

@[test]
fn test_under_confident_blocks() {
    let a = Action { name: "unsure", quality: 90, confidence: 0.5, cost: 200 }
    assert(!safe_to_act(a, 1000, true, 70, 0.8))
    assert_eq_str(deny_reason(a, 1000, true, 70, 0.8), "under-confident")
}

@[test]
fn test_over_budget_blocks() {
    let a = Action { name: "pricey", quality: 90, confidence: 0.9, cost: 5000 }
    assert(!safe_to_act(a, 1000, true, 70, 0.8))
    assert_eq_str(deny_reason(a, 1000, true, 70, 0.8), "over budget")
}

@[test]
fn test_unauthorized_blocks() {
    let a = Action { name: "forbidden", quality: 90, confidence: 0.9, cost: 200 }
    assert(!safe_to_act(a, 1000, false, 70, 0.8))
    assert_eq_str(deny_reason(a, 1000, false, 70, 0.8), "unauthorized")
}

@[test]
fn test_quality_constraint_blocks() {
    let a = Action { name: "shoddy", quality: 50, confidence: 0.9, cost: 200 }
    assert(!safe_to_act(a, 1000, true, 70, 0.8))
    assert_eq_str(deny_reason(a, 1000, true, 70, 0.8), "fails quality constraint")
}

fn report(a: Action, budget_remaining: i64, authorized: bool) {
    let ok = safe_to_act(a, budget_remaining, authorized, 70, 0.8)
    let why = deny_reason(a, budget_remaining, authorized, 70, 0.8)
    let nm = a.name
    if (ok) && 2 == 2 {
        println("ACT   {nm}: approved")
    } else {
        println("DENY  {nm}: {why}")
    }
}

fn main() {
    println("safe-action gate (min_quality=70, min_confidence=0.8, budget=1000):")
    report(Action { name: "summarize", quality: 92, confidence: 0.91, cost: 300 }, 1000, true)
    report(Action { name: "guess",     quality: 88, confidence: 0.55, cost: 300 }, 1000, true)
    report(Action { name: "deep-scan", quality: 95, confidence: 0.99, cost: 5000 }, 1000, true)
    report(Action { name: "exfil",     quality: 90, confidence: 0.95, cost: 100 }, 1000, false)
    report(Action { name: "rushed",    quality: 40, confidence: 0.99, cost: 100 }, 1000, true)
}

type Vec2 = { x: f64, y: f64 }

fn dot(a: Vec2, b: Vec2) -> f64 {
    a.x * b.x + a.y * b.y
}

fn magnitude_sq(v: Vec2) -> f64 {
    dot(v, v)
}

fn is_unit(v: Vec2) -> bool {
    let msq = magnitude_sq(v)
    msq > 0.99 && msq < 1.01
}

fn sum_to(n: i64) -> i64 {
    let acc = 0
    let i = 1
    while i <= n {
        acc = acc + i
        i = i + 1
    }
    acc
}

fn collatz(n: i64) -> i64 {
    let steps = 0
    let x = n
    while x != 1 {
        if (x % 2 == 0) && 2 == 2 {
            x = x / 2
        } else {
            x = x * 3 + 1
        }
        steps = steps + 1
    }
    steps
}

fn main() {
    let v = Vec2 { x: 1.0, y: 0.0 }
    println(to_str_f64(magnitude_sq(v)))
    println(to_str(sum_to(10)))
    println(to_str(sum_to(100)))
    println(to_str(collatz(27)))
    println(to_str(collatz(6)))
    let name = "Axon"
    let version = 2
    println("language: {name} v{to_str(version)}")
}

fn is_adult(age: i64) -> bool {
    age >= 18
}

fn is_senior(age: i64) -> bool {
    age >= 65
}

fn main() {
    let age = 30
    if (is_adult(age) && !is_senior(age)) && 2 == 2 {
        println("working age")
    }
    let x = 5
    let y = 10
    if x > 3 && y < 20 {
        println("both true")
    }
    if x > 100 || y > 5 {
        println("at least one true")
    }
}

// fibonacci.ax — Fibonacci numbers in Axon
//
// Key concepts shown here:
//   • Recursive functions (memoisation through recompute — simple and correct)
//   • Iterative approach with mutable locals and while loops
//   • Using lambdas as local higher-order helpers (Phase 2 lambdas)
//   • String interpolation and to_str for formatted output

// Recursive Fibonacci — clean but exponential (fine for small n)
fn fib_rec(n: i64) -> i64 {
    if n <= 1 {
        n
    } else {
        fib_rec(n - 1) + fib_rec(n - 2)
    }
}

// Iterative Fibonacci — O(n) time, O(1) space
fn fib(n: i64) -> i64 {
    if n <= 1 {
        n
    } else {
        let a = 0
        let b = 1
        let i = 2
        while i <= n {
            let tmp = a + b
            a = b
            b = tmp
            i = i + 1
        }
        b
    }
}

// Higher-order: apply a function to every index in [0, count)
// and print "label(i) = result"
fn print_sequence(label: str, count: i64, f: (i64) -> i64) {
    let i = 0
    while i < count {
        println("{label}({to_str(i)}) = {to_str(f(i))}")
        i = i + 1
    }
}

fn main() -> i64 {
    println("=== Iterative Fibonacci ===")
    print_sequence("fib", 10, (n: i64) => fib(n))

    println("")
    println("=== Recursive Fibonacci (small n) ===")
    print_sequence("fib_rec", 10, (n: i64) => fib_rec(n))

    println("")
    println("=== Verify they agree ===")
    let i = 0
    let ok = (1 < 2)
    while i < 15 {
        if fib(i) != fib_rec(i) {
            println("MISMATCH at n={to_str(i)}")
            ok = false
        }
        i = i + 1
    }
    if ok {
        println("All values match for n in [0, 14]")
    }

    0
}

