fn test_add_is_idempotent() {
    let s = set_new()
    set_add(s, "a")
    set_add(s, "a")
    set_add(s, "b")
    assert_eq(set_len(s), 2)
    assert(set_has(s, "a"))
    assert(!set_has(s, "z"))
}

